import XCTest
@testable import ColorComposerCore

/// Solver parity corpus replay (issue #39).
///
/// The corpus is generated by the Elixir `color_matching` service
/// (`mix parity.generate`, viamin/color_matching#111 / #112) and committed
/// verbatim at `Fixtures/parity/v1/corpus.json`. Replaying it here asserts
/// that `WeightedSquaredErrorScorer` and `CompositionSolver` agree with the
/// server's `ColorMatching.WeightedSquaredError` on every selection —
/// including tie-breaking (earliest index wins), missing-measurement
/// exclusion, and channel weighting.
///
/// Corpus consumption and the refresh procedure are documented in
/// `docs/solver-parity-corpus.md`.
final class SolverParityCorpusTests: XCTestCase {
    /// The corpus `algorithm_version` this suite understands. Bump when a
    /// refreshed corpus changes algorithm semantics.
    private static let supportedAlgorithmVersion = 1

    private static let weightKeyPaths: [LightingCondition: WritableKeyPath<ChannelWeights, Double>] = [
        .white: \.white, .red: \.red, .green: \.green, .blue: \.blue, .lps: \.lps
    ]

    // MARK: - Corpus contract

    func testCorpusDeclaresSupportedAlgorithmVersion() throws {
        XCTAssertEqual(try loadCorpus().algorithmVersion, Self.supportedAlgorithmVersion)
    }

    func testCorpusMetadataMatchesCanonicalContract() throws {
        let corpus = try loadCorpus()
        XCTAssertEqual(Set(corpus.lightSources), Set(LightingCondition.allCases.map(\.rawValue)))
        XCTAssertEqual(corpus.missingPolicy, "excluded-when-any-positive-weight-channel-missing")
        XCTAssertEqual(corpus.scorer, "ColorMatching.WeightedSquaredError")
        XCTAssertEqual(corpus.selection, "earliest-index-wins")
    }

    /// Index-based expectations only stay meaningful while palette entries
    /// arrive zero-based and in order; pin that invariant before replaying.
    func testScenarioPaletteIndicesAreZeroBasedAndOrdered() throws {
        for scenario in try loadCorpus().scenarios {
            XCTAssertEqual(scenario.palette.map(\.index), Array(scenario.palette.indices), scenario.id)
        }
    }

    /// The corpus must keep covering the cases the issue calls out: ties,
    /// exclusions, no-winner scenarios, and unknown-channel weights.
    func testCorpusCoversTiesExclusionsAndUnknownChannelWeights() throws {
        let scenarios = try loadCorpus().scenarios
        XCTAssertTrue(scenarios.contains { $0.expected.tieBroke == true }, "tie coverage missing")
        XCTAssertTrue(scenarios.contains { $0.expected.selectedIndex == nil }, "no-winner coverage missing")
        XCTAssertTrue(scenarios.contains { $0.weights.keys.contains { LightingCondition(rawValue: $0) == nil } },
                      "unknown-channel weight coverage missing")
        XCTAssertTrue(scenarios.contains { scenario in
            scenario.expected.scores.contains { $0.score.isExcluded }
        }, "exclusion coverage missing")
    }

    // MARK: - Scorer parity

    /// Every scenario replays through the scorer exactly: per-candidate
    /// scores (including exclusions), the selected index and error, and the
    /// tie set with the earliest-index-wins policy.
    func testScorerMatchesCorpusExpectations() throws {
        let scorer = WeightedSquaredErrorScorer()
        for scenario in try loadCorpus().scenarios {
            let replayed = try scoreCandidates(scenario, scorer: scorer)
            assertScores(replayed, match: scenario.expected, scenario: scenario.id)
            assertSelection(Self.selection(from: replayed), matches: scenario)
        }
    }

    private func assertSelection(
        _ outcome: SelectionOutcome,
        matches scenario: ParityScenario
    ) {
        let expected = scenario.expected
        XCTAssertEqual(outcome.index, expected.selectedIndex, scenario.id)
        if let expectedError = expected.error {
            XCTAssertEqual(outcome.error ?? .nan, expectedError, accuracy: 1e-12, scenario.id)
        } else {
            XCTAssertNil(outcome.error, scenario.id)
        }
        XCTAssertEqual(outcome.tied, expected.tiedIndices, scenario.id)
        XCTAssertEqual(outcome.tieBroke, expected.tieBroke, scenario.id)
        if let selectedIndex = outcome.index {
            XCTAssertEqual(scenario.palette[selectedIndex].hexColor, expected.selectedHexColor, scenario.id)
        } else {
            XCTAssertNil(expected.selectedHexColor, scenario.id)
        }
    }

    // MARK: - Solver parity

    /// Solver-level replay through the default fast path: the 1×1 grid built
    /// from the corpus target must select the corpus-expected palette entry
    /// with the corpus-expected error, and report the corpus-expected number
    /// of excluded candidates.
    func testSolverFastPathSelectionMatchesCorpus() throws {
        let solver = CompositionSolver() // default WeightedSquaredErrorScorer → fast path
        for scenario in try solverExpressibleScenarios() {
            let result = try solveScenario(scenario, solver: solver)
            let expected = scenario.expected

            XCTAssertEqual(result.colorIndex(x: 0, y: 0), expected.selectedIndex, scenario.id)
            XCTAssertEqual(result.excludedCandidateCount, expected.excludedCount, scenario.id)
            assertCellError(result, matches: expected, scenario: scenario.id)
        }
    }

    /// A winnerless scenario leaves the cell unmatched with infinite error;
    /// a winner records the corpus-expected error exactly.
    private func assertCellError(
        _ result: CompositionResult,
        matches expected: ParityExpectation,
        scenario id: String
    ) {
        guard let expectedError = expected.error else {
            XCTAssertEqual(result.error(x: 0, y: 0), Double.infinity, id)
            XCTAssertEqual(result.unmatchedCellCount, 1, id)
            return
        }
        XCTAssertEqual(result.error(x: 0, y: 0), expectedError, accuracy: 1e-12, id)
    }

    /// The corpus's tie policy must hold identically on the solver's general
    /// (custom-scorer) path: a wrapped `WeightedSquaredErrorScorer` selects
    /// the same entries, so tie-breaking cannot drift between paths.
    func testSolverGeneralPathAgreesWithFastPath() throws {
        let fast = CompositionSolver()
        let general = CompositionSolver(scorer: WrappedWeightedSquaredErrorScorer())
        for scenario in try solverExpressibleScenarios() {
            let fastResult = try solveScenario(scenario, solver: fast)
            let generalResult = try solveScenario(scenario, solver: general)
            XCTAssertEqual(generalResult.colorIndices, fastResult.colorIndices, scenario.id)
            XCTAssertEqual(generalResult.colorIndex(x: 0, y: 0), scenario.expected.selectedIndex, scenario.id)
        }
    }

    /// Only a target that itself misses a positive-weight channel cannot be
    /// expressed through the solver (grids always supply values). Pin exactly
    /// which corpus scenarios are skipped so a corpus refresh cannot silently
    /// shrink solver-level coverage.
    func testOnlyTargetMissingScenariosAreNotSolverExpressible() throws {
        let corpus = try loadCorpus()
        let skipped = corpus.scenarios.filter { !Self.isSolverExpressible($0) }.map(\.id)
        XCTAssertEqual(skipped, ["missing-target-excluded"])
        XCTAssertFalse(try solverExpressibleScenarios().isEmpty)
    }

    // MARK: - Replay helpers

    private func loadCorpus(file: StaticString = #filePath) throws -> ParityCorpus {
        try JSONDecoder().decode(ParityCorpus.self, from: Data(contentsOf: Self.corpusURL(file: file)))
    }

    private static func corpusURL(file: StaticString) throws -> URL {
        if let override = ProcessInfo.processInfo.environment["PARITY_CORPUS_PATH"], !override.isEmpty {
            return URL(fileURLWithPath: override)
        }
        return URL(fileURLWithPath: "\(file)")
            .deletingLastPathComponent()
            .appendingPathComponent("Fixtures/parity/v1/corpus.json")
    }

    private func solverExpressibleScenarios() throws -> [ParityScenario] {
        try loadCorpus().scenarios.filter(Self.isSolverExpressible)
    }

    private static func isSolverExpressible(_ scenario: ParityScenario) -> Bool {
        domainWeights(scenario.weights).activeConditions.allSatisfy {
            scenario.target.channels[$0.rawValue] != nil
        }
    }

    private static func domainWeights(_ raw: [String: Double]) -> ChannelWeights {
        var weights = ChannelWeights()
        for (key, value) in raw {
            guard let condition = LightingCondition(rawValue: key), value > 0 else { continue }
            weights[keyPath: weightKeyPaths[condition]!] = value
        }
        return weights
    }

    private func domainColor(_ entry: ParityPaletteEntry) throws -> PaletteColor {
        let rgb = try XCTUnwrap(RGBColor(hex: entry.hexColor), "unparseable hex in corpus: \(entry.hexColor)")
        return PaletteColor(id: entry.index, hex: entry.hexColor, rgb: rgb, responses: domainResponses(entry.channels))
    }

    private func domainTarget(_ vector: ParityVector) -> TargetResponseVector {
        var brightness: [LightingCondition: Double] = [:]
        for (key, value) in vector.channels {
            if let condition = LightingCondition(rawValue: key) { brightness[condition] = value }
        }
        return TargetResponseVector(brightness)
    }

    private func domainResponses(_ channels: [String: Double]) -> [LightingCondition: IlluminationResponse] {
        channels.reduce(into: [:]) { partial, pair in
            if let condition = LightingCondition(rawValue: pair.key) {
                partial[condition] = IlluminationResponse(brightness: pair.value)
            }
        }
    }

    private func scoreCandidates(
        _ scenario: ParityScenario,
        scorer: CompositionScorer
    ) throws -> [(index: Int, result: ScorerResult)] {
        let target = domainTarget(scenario.target)
        let weights = Self.domainWeights(scenario.weights)
        return try scenario.palette.map { entry in
            (entry.index, scorer.score(candidate: try domainColor(entry), target: target, weights: weights))
        }
    }

    /// Lowest score wins with earliest-index tie-breaking — the corpus
    /// `selection: "earliest-index-wins"` policy, spelled out explicitly so
    /// the tie rule under test never rides on stdlib min(by:) details.
    private static func selection(from results: [(index: Int, result: ScorerResult)]) -> SelectionOutcome {
        var winner: (index: Int, score: Double)?
        for entry in results {
            guard case .score(let value) = entry.result, value < (winner?.score ?? .infinity) else { continue }
            winner = (entry.index, value)
        }
        guard let champion = winner else { return SelectionOutcome(index: nil, error: nil, tied: [], tieBroke: nil) }
        let tied = results.compactMap { entry -> Int? in
            guard case .score(let value) = entry.result, value == champion.score else { return nil }
            return entry.index
        }
        return SelectionOutcome(index: champion.index, error: champion.score, tied: tied, tieBroke: tied.count > 1)
    }

    private func assertScores(
        _ replayed: [(index: Int, result: ScorerResult)],
        match expected: ParityExpectation,
        scenario id: String
    ) {
        XCTAssertEqual(replayed.map(\.index), expected.scores.map(\.index), id)
        for (candidate, expectedScore) in zip(replayed, expected.scores) {
            switch (candidate.result, expectedScore.score) {
            case (.excluded, .excluded):
                continue
            case (.score(let value), .excluded):
                XCTFail("\(id): candidate \(candidate.index) scored \(value), expected excluded")
            case (.excluded, .value(let expected)):
                XCTFail("\(id): candidate \(candidate.index) excluded, expected score \(expected)")
            case (.score(let value), .value(let expected)):
                XCTAssertEqual(value, expected, accuracy: 1e-12, "\(id): candidate \(candidate.index)")
            }
        }
    }

    private func solveScenario(_ scenario: ParityScenario, solver: CompositionSolver) throws -> CompositionResult {
        try solver.solve(
            palette: scenario.palette.map(domainColor),
            sourceGrids: targetGrids(scenario),
            weights: Self.domainWeights(scenario.weights)
        )
    }

    private func targetGrids(_ scenario: ParityScenario) -> [LightingCondition: BrightnessGrid] {
        // Callers only pass solver-expressible scenarios, so every active
        // channel is present on the target; the fallback is unreachable.
        var grids: [LightingCondition: BrightnessGrid] = [:]
        for (condition, _) in Self.domainWeights(scenario.weights).activeEntries {
            let value = scenario.target.channels[condition.rawValue] ?? 0
            grids[condition] = BrightnessGrid(width: 1, height: 1, values: [value])
        }
        return grids
    }
}

/// The corpus-expected outcome of one scenario, reconstructed from replayed
/// scores: winner, winning error, the full tie set, and whether the winner
/// needed the earliest-index tie-break.
private struct SelectionOutcome {
    let index: Int?
    let error: Double?
    let tied: [Int]
    let tieBroke: Bool?
}

/// Forces `CompositionSolver` onto its general (per-candidate scorer) path
/// while scoring identically to `WeightedSquaredErrorScorer`, so tie-breaking
/// parity can be compared across both solver paths.
private struct WrappedWeightedSquaredErrorScorer: CompositionScorer {
    private let base = WeightedSquaredErrorScorer()

    func score(
        candidate: PaletteColor,
        target: TargetResponseVector,
        weights: ChannelWeights
    ) -> ScorerResult {
        base.score(candidate: candidate, target: target, weights: weights)
    }
}

// MARK: - Corpus wire format (viamin/color_matching priv/parity/v1/corpus.json)

private struct ParityCorpus: Codable {
    let algorithmVersion: Int
    let lightSources: [String]
    let missingPolicy: String
    let scorer: String
    let selection: String
    let scenarios: [ParityScenario]

    enum CodingKeys: String, CodingKey {
        case algorithmVersion = "algorithm_version"
        case lightSources = "light_sources"
        case missingPolicy = "missing_policy"
        case scorer
        case selection
        case scenarios
    }
}

private struct ParityScenario: Codable {
    let id: String
    let description: String
    let weights: [String: Double]
    let target: ParityVector
    let palette: [ParityPaletteEntry]
    let expected: ParityExpectation
}

private struct ParityVector: Codable {
    let channels: [String: Double]
    let hexColor: String?
    let index: Int?

    enum CodingKeys: String, CodingKey {
        case channels
        case hexColor = "hex_color"
        case index
    }
}

private struct ParityPaletteEntry: Codable {
    let index: Int
    let hexColor: String
    let channels: [String: Double]

    enum CodingKeys: String, CodingKey {
        case index
        case hexColor = "hex_color"
        case channels
    }
}

private struct ParityExpectation: Codable {
    let selectedIndex: Int?
    let selectedHexColor: String?
    let error: Double?
    let tieBroke: Bool?
    let tiedIndices: [Int]
    let scores: [ParityScoreEntry]

    enum CodingKeys: String, CodingKey {
        case selectedIndex = "selected_index"
        case selectedHexColor = "selected_hex_color"
        case error
        case tieBroke = "tie_broke"
        case tiedIndices = "tied_indices"
        case scores
    }

    /// Number of candidates the corpus marks as excluded.
    var excludedCount: Int {
        scores.filter { $0.score.isExcluded }.count
    }
}

private struct ParityScoreEntry: Codable {
    let index: Int
    let score: ParityScoreValue
}

/// A corpus score is either a number or the literal string "excluded".
private enum ParityScoreValue: Equatable {
    case value(Double)
    case excluded

    var isExcluded: Bool { self == .excluded }
}

extension ParityScoreValue: Codable {
    init(from decoder: Decoder) throws {
        let container = try decoder.singleValueContainer()
        if let value = try? container.decode(Double.self) {
            self = .value(value)
        } else if let literal = try? container.decode(String.self), literal == "excluded" {
            self = .excluded
        } else {
            throw DecodingError.dataCorrupted(.init(
                codingPath: decoder.codingPath,
                debugDescription: "Corpus score must be a number or \"excluded\""
            ))
        }
    }

    func encode(to encoder: Encoder) throws {
        var container = encoder.singleValueContainer()
        switch self {
        case .value(let value): try container.encode(value)
        case .excluded: try container.encode("excluded")
        }
    }
}
